mapper.select:
SELECT 
  id, task_id, batch_no, export_rows, file_path, sftp_status, execute_status, error_msg,
  DATE_FORMAT(start_time, '%Y-%m-%d %H:%i:%s') as start_time,
  DATE_FORMAT(end_time, '%Y-%m-%d %H:%i:%s') as end_time,
  DATE_FORMAT(create_time, '%Y-%m-%d %H:%i:%s') as create_time
FROM b_data_export_log


    AND task_id = #{taskId}


    AND batch_no LIKE CONCAT('%', #{batchNo}, '%')


    AND execute_status = #{executeStatus}


    AND start_time >= #{startTimeStart}


    AND start_time <= #{startTimeEnd}


ORDER BY create_time DESC

